USE hospital_system;
CREATE TABLE IF NOT EXISTS department (department_id BIGINT AUTO_INCREMENT PRIMARY KEY, department_name VARCHAR(100) NOT NULL, description VARCHAR(500));
CREATE TABLE IF NOT EXISTS patient (patient_id BIGINT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, date_of_birth DATE NOT NULL, gender VARCHAR(20) NOT NULL, phone VARCHAR(20) NOT NULL, email VARCHAR(150), address VARCHAR(300), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS doctor (doctor_id BIGINT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, specialization VARCHAR(120) NOT NULL, department_id BIGINT NOT NULL, phone VARCHAR(20) NOT NULL, consultation_fee DECIMAL(10,2) NOT NULL, available_from TIME NOT NULL, available_to TIME NOT NULL);
CREATE TABLE IF NOT EXISTS appointment (appointment_id BIGINT AUTO_INCREMENT PRIMARY KEY, patient_id BIGINT NOT NULL, doctor_id BIGINT NOT NULL, appointment_date DATE NOT NULL, appointment_time TIME NOT NULL, reason VARCHAR(500), status VARCHAR(20) NOT NULL DEFAULT 'BOOKED', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hospital_service (service_id BIGINT AUTO_INCREMENT PRIMARY KEY, service_name VARCHAR(100) NOT NULL, description VARCHAR(300), price DECIMAL(10,2) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS bill (bill_id BIGINT AUTO_INCREMENT PRIMARY KEY, patient_id BIGINT NOT NULL, appointment_id BIGINT NULL, bill_date DATE NOT NULL, subtotal DECIMAL(12,2) NOT NULL DEFAULT 0, tax DECIMAL(12,2) NOT NULL DEFAULT 0, total_amount DECIMAL(12,2) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'UNPAID');
CREATE TABLE IF NOT EXISTS bill_item (bill_item_id BIGINT AUTO_INCREMENT PRIMARY KEY, bill_id BIGINT NOT NULL, service_id BIGINT NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, amount DECIMAL(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS payment (payment_id BIGINT AUTO_INCREMENT PRIMARY KEY, bill_id BIGINT NOT NULL, payment_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, amount DECIMAL(12,2) NOT NULL, payment_method VARCHAR(30) NOT NULL, reference_no VARCHAR(100));
